// eslint-disable-next-line @typescript-eslint/no-namespace
namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokHromadneKonChodTab extends GContentBase {

       
        pokDoklady: Gordic.Hpl.Interface.GPokDokladDto[];

        onContentReady() {

            var that = this;

            this.title = "Hromadný kontrolní chod";
            this.setBreadcrumbs([{ caption: this.title, defaultAction: true }]);

            var gf = new Gordic.Data.GridFormat();
            gf.addTextColumn({
                name: "ixp",
                caption: "jres:31302005", //RC 31302005 : PID
                sortable: false
            })

            const gridActionDetail = new GAction($.extend(true, Gordic.Eko.Action.actionDetail({
                    run: function (ev, ctx) {
                    that.navigate("Gordic.Pok.WebClient.GPokDetailDokladuTab", {
                        ixp: ctx.cellInfo.data.ixp,
                        newPodani: false,
                        Id: "GPokDetailDokladu#"
                    });
                    },
                    enabled: true
                }), { name: "actDetail" }))


            this.navigate<Gordic.Eko.Components.TwoStepsOptions<Gordic.Hpl.Interface.GPokDokladDto>>(Gordic.Eko.Components.TwoStepsContent, {
                title: "Hromadný kontrolní chod pokladních dokladů",
                gridFormat: gf,
                keys: "ixp",
                data: this.pokDoklady,
                indicatorType: "KPI",
                firstStep: {
                    title: "Hromadný kontrolní chod pokladních dokladů",
                    description: "Hromadný kontrolní chod",
                    gridTabTitle: "Vybrané pokladní doklady",
                    defaultAction: gridActionDetail,
                    checkAction: (model, data) => {


                        var view = new Gordic.Data.View(data, { key: "ixp" });
                        var ixpArray = data.map(function (d) { return d.ixp; });
                        let i = 0;

                        let def = $.Deferred();

                        ixpArray.forEach(function (x) {
                            that.call("KontrolniChod", { ixp: x, dotaz: true, dotazZpz: true })
                                .done(function (data) {
                                    view.getDataRows(true).forEach(function (meta) {
                                        if (meta.data.ixp === x) {
                                            i = i + 1;

                                            if (data.stav == 0) {
                                                meta.data.wiz_kind = Gordic.Isl.GOperationResultKind.Success;
                                                meta.data.wiz_txt_err = "Kontrolní chod proběhl bez chyb!";
                                                meta.data.wiz_check = true;

                                            } else if (data.stav == 1 || data.stav == 3) {

                                                //question
                                                meta.data.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                                meta.data.wiz_txt_err = data.text;

                                            } else if (data.stav == 2 || data.stav == 4) {
                                                meta.data.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                                meta.data.wiz_txt_err = data.text;
                                            }                                           

                                            if (i == ixpArray.length) {
                                                def.resolve(view)
                                            }
                                        }

                                        //Poznámka ze starého wizarda a jaké jsou stavy kontrolního chodu
                                        //row.stav = data.stav;
                                        //row.vysledek = data.text;
                                        //if (data.table != null)
                                        //    row.table = data.table;  
                                        //   case 0: return { icon: "fa-check-circle", text: "OK", tooltip: "" };
                                        //                            case 1: return { icon: "fa-question-circle", text: "?",tooltip: "" };
                                        //                            case 3: return { icon: "fa-question-circle", text: "?",tooltip: "" };
                                        //                            case 2: return { icon: "fa-times-circle", text: "CHYBA", tooltip: "" };
                                        //                            case 4: return { icon: "fa-times-circle", text: "CHYBA", tooltip: "" };



                                    });

                                });

                        });

                        return def.promise();


                    },
                    nextActionName: "Pokračovat",
                    nextAction: (model, data) => {

                        return $.Deferred().resolve(data);

                    },
                },

                lastStep:
                {
                    title: "Výsledek",
                    gridTabTitle: "Pokladní doklady prošlé kontrolním chodem",
                    description: "Výsledek hromadného kontrolního chodu"
                },
                completeDelegate: (view) => {

                    that.close();
                },
                cancelDelegate: () => {
                    that.close();
                },
            }, { title: "Hromadný kontrolní chod pokladních dokladů" });

        }


    }


}


